// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface ICallback {
    function onComplete(uint256 requestId, bytes calldata result) external;
}

contract MultiTenantOracle {
    struct Tenant {
        address admin;
        uint256 balance;
        bool active;
        mapping(uint256 => Request) requests;
    }

    struct Request {
        address callbackTarget;
        bytes4 callbackSelector;
        uint256 tenantId;
        bool fulfilled;
        uint256 gasLimit;
    }

    mapping(uint256 => Tenant) public tenants;
    mapping(uint256 => Request) public pendingRequests;
    mapping(uint256 => mapping(address => bool)) public tenantApprovedTargets;
    uint256 public nextTenantId;
    uint256 public nextRequestId;
    address public oracle;

    event RequestCreated(uint256 indexed tenantId, uint256 indexed requestId);
    event TenantDeactivated(uint256 indexed tenantId);
    event CallbackExecuted(uint256 indexed requestId, bool success);

    modifier onlyOracle() {
        require(msg.sender == oracle, "Not oracle");
        _;
    }

    modifier onlyTenantAdmin(uint256 tenantId) {
        require(tenants[tenantId].admin == msg.sender, "Not admin");
        _;
    }

    constructor(address _oracle) {
        oracle = _oracle;
    }

    function registerTenant() external payable returns (uint256) {
        require(msg.value >= 0.1 ether, "Min deposit");
        uint256 tid = nextTenantId++;
        tenants[tid].admin = msg.sender;
        tenants[tid].balance = msg.value;
        tenants[tid].active = true;
        return tid;
    }

    function approveTarget(uint256 tenantId, address target) external onlyTenantAdmin(tenantId) {
        tenantApprovedTargets[tenantId][target] = true;
    }

    function createRequest(
        uint256 tenantId,
        address callbackTarget,
        bytes4 callbackSelector,
        uint256 gasLimit
    ) external onlyTenantAdmin(tenantId) returns (uint256) {
        require(tenants[tenantId].active, "Tenant inactive");
        require(tenants[tenantId].balance >= 0.01 ether, "Insufficient balance");
        require(gasLimit <= 500000, "Gas limit too high");
        require(tenantApprovedTargets[tenantId][callbackTarget], "Target not approved");

        uint256 rid = nextRequestId++;
        pendingRequests[rid] = Request({
            callbackTarget: callbackTarget,
            callbackSelector: callbackSelector,
            tenantId: tenantId,
            fulfilled: false,
            gasLimit: gasLimit
        });

        tenants[tenantId].balance -= 0.01 ether;
        emit RequestCreated(tenantId, rid);
        return rid;
    }

    function deactivateTenant(uint256 tenantId) external onlyTenantAdmin(tenantId) {
        tenants[tenantId].active = false;
        uint256 refund = tenants[tenantId].balance;
        tenants[tenantId].balance = 0;
        emit TenantDeactivated(tenantId);
        (bool sent, ) = msg.sender.call{value: refund}("");
        require(sent, "Refund failed");
    }

    function fulfillRequest(uint256 requestId, bytes calldata result) external onlyOracle {
        Request storage req = pendingRequests[requestId];
        require(!req.fulfilled, "Already fulfilled");
        require(tenants[req.tenantId].active, "Tenant no longer active");

        // Cache values before state change
        address target = req.callbackTarget;
        bytes4 selector = req.callbackSelector;
        uint256 gasLimit = req.gasLimit;
        uint256 tenantId = req.tenantId;

        // Mark fulfilled
        req.fulfilled = true;

        // Verify callback target is still approved for this tenant
        require(tenantApprovedTargets[tenantId][target], "Target no longer approved");

        // Execute callback with gas limit
        bytes memory callData = abi.encodeWithSelector(selector, requestId, result);
        (bool success, ) = target.call{gas: gasLimit}(callData);
        emit CallbackExecuted(requestId, success);
    }

    function migrateRequest(uint256 requestId, uint256 newTenantId) external {
        Request storage req = pendingRequests[requestId];
        require(!req.fulfilled, "Already fulfilled");
        require(tenants[req.tenantId].admin == msg.sender, "Not original admin");
        require(tenants[newTenantId].active, "New tenant inactive");
        require(tenantApprovedTargets[newTenantId][req.callbackTarget], "Target not approved in new tenant");

        // Migration: update tenant reference
        req.tenantId = newTenantId;
    }

    function updateCallback(uint256 requestId, address newTarget) external {
        Request storage req = pendingRequests[requestId];
        require(!req.fulfilled, "Already fulfilled");
        require(tenants[req.tenantId].admin == msg.sender, "Not admin");
        require(tenantApprovedTargets[req.tenantId][newTarget], "Target not approved");

        // Update callback target with tenant boundary enforcement
        req.callbackTarget = newTarget;
    }

    function batchFulfill(uint256[] calldata requestIds, bytes[] calldata results) external onlyOracle {
        require(requestIds.length == results.length, "Length mismatch");
        for (uint256 i = 0; i < requestIds.length; i++) {
            Request storage req = pendingRequests[requestIds[i]];
            if (req.fulfilled) continue;
            if (!tenants[req.tenantId].active) continue;

            address target = req.callbackTarget;
            bytes4 selector = req.callbackSelector;
            uint256 gasLimit = req.gasLimit;
            uint256 tenantId = req.tenantId;

            if (!tenantApprovedTargets[tenantId][target]) continue;

            req.fulfilled = true;

            bytes memory callData = abi.encodeWithSelector(selector, requestIds[i], results[i]);
            (bool success, ) = target.call{gas: gasLimit}(callData);
            emit CallbackExecuted(requestIds[i], success);
        }
    }

    receive() external payable {}
}
